using System;
using SilentOrders.Core;

namespace SilentOrders.Rendering
{
    public static class PawnSprites
    {
        public sealed class Sprite
        {
            public readonly int W;
            public readonly int H;
            public readonly byte[] RGBA;
            public Sprite(int w, int h, string bytes)
            {
                W = w;
                H = h;
                using (System.IO.MemoryStream stream = new System.IO.MemoryStream(System.Convert.FromBase64String(bytes)))
                {
                    using (System.IO.Compression.GZipStream gZipStream = new System.IO.Compression.GZipStream(stream, System.IO.Compression.CompressionMode.Decompress))
                    {
                        using (System.IO.MemoryStream memoryStream = new System.IO.MemoryStream())
                        {
                            gZipStream.CopyTo(memoryStream);
                            RGBA = memoryStream.ToArray();
                        }
                    }
                }
            }
        }

